#!/usr/bin/env python3
"""
xiaohongshu-mcp的正确使用方式
关键: 使用Mcp-Session-Id header并保持快速连续调用
"""
import json
import requests
import math
from datetime import datetime
from pathlib import Path
import time

MCP_URL = "http://localhost:18060/mcp"

class XHS_MCP_Client:
    """小红书MCP客户端"""

    def __init__(self):
        self.session = requests.Session()
        self.session_id = None
        self.initialized = False

    def init_session(self):
        """初始化MCP session"""
        init_payload = {
            "jsonrpc": "2.0",
            "id": 1,
            "method": "initialize",
            "params": {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {
                    "name": "xhs-viral-finder",
                    "version": "1.0.0"
                }
            }
        }

        resp = self.session.post(MCP_URL, json=init_payload)
        result = resp.json()

        if "result" in result:
            # 获取session ID
            self.session_id = resp.headers.get('Mcp-Session-Id')
            if self.session_id:
                self.session.headers.update({'Mcp-Session-Id': self.session_id})

            # 发送initialized通知
            notif_payload = {
                "jsonrpc": "2.0",
                "method": "notifications/initialized"
            }
            self.session.post(MCP_URL, json=notif_payload)

            self.initialized = True
            print(f"[INFO] MCP session初始化成功 (ID: {self.session_id})")
            return True
        else:
            print(f"[ERROR] MCP初始化失败: {result}")
            return False

    def call_tool(self, tool_name, arguments):
        """调用MCP工具"""
        if not self.initialized:
            if not self.init_session():
                return None

        payload = {
            "jsonrpc": "2.0",
            "id": int(time.time() * 1000) % 10000,
            "method": "tools/call",
            "params": {
                "name": tool_name,
                "arguments": arguments
            }
        }

        try:
            resp = self.session.post(MCP_URL, json=payload, timeout=60)
            result = resp.json()

            if "result" in result:
                return result["result"]
            else:
                print(f"[WARN] 工具调用失败: {result.get('error', {})}")
                return None
        except Exception as e:
            print(f"[ERROR] 请求异常: {e}")
            return None

    def search_notes(self, keyword):
        """搜索笔记"""
        print(f"[INFO] 搜索关键词: {keyword}")
        result = self.call_tool("search_feeds", {"keyword": keyword})

        if not result or "feeds" not in result:
            print(f"[WARN] 关键词 '{keyword}' 无结果")
            return []

        feeds = result["feeds"]
        print(f"[INFO] 找到 {len(feeds)} 条笔记")

        candidates = []
        for note in feeds:
            try:
                likes = note.get("interaction_info", {}).get("liked_count", 0)
                if likes >= 1000:
                    candidates.append({
                        "note_id": note.get("note_id", ""),
                        "title": note.get("title", ""),
                        "likes": likes,
                        "collects": note.get("interaction_info", {}).get("collected_count", 0),
                        "comments": note.get("interaction_info", {}).get("comment_count", 0),
                        "user_id": note.get("user", {}).get("user_id", ""),
                        "xsec_token": note.get("user", {}).get("xsec_token", ""),
                        "note_url": f"https://www.xiaohongshu.com/explore/{note.get('note_id', '')}"
                    })
            except Exception as e:
                continue

        print(f"[INFO] 符合点赞初筛(≥1000): {len(candidates)} 条")
        return candidates

    def get_user_followers(self, user_id, xsec_token):
        """获取用户粉丝数"""
        result = self.call_tool("user_profile", {
            "user_id": user_id,
            "xsec_token": xsec_token
        })

        if result and "userBasicInfo" in result:
            return result["userBasicInfo"].get("fans", -1)
        return -1

def main():
    """主执行流程"""
    print("=" * 60)
    print("🔍 小红书低粉爆文抓取工具 - 正确MCP方式")
    print("=" * 60)
    print()

    # 初始化客户端
    client = XHS_MCP_Client()
    if not client.init_session():
        print("[ERROR] 无法初始化MCP客户端")
        return

    # 搜索关键词
    keywords = ["金融", "理财"]
    all_candidates = []

    for keyword in keywords:
        notes = client.search_notes(keyword)
        all_candidates.extend(notes)

    print(f"\n[INFO] 总共收集 {len(all_candidates)} 条候选笔记")

    if len(all_candidates) == 0:
        print("[WARN] 未找到符合条件的笔记")
        return

    # 去重用户
    unique_users = {}
    for c in all_candidates:
        uid = c["user_id"]
        if uid and uid not in unique_users:
            unique_users[uid] = c["xsec_token"]

    print(f"[INFO] 发现 {len(unique_users)} 个独立用户")

    # 获取粉丝数
    print(f"\n[INFO] 开始获取用户粉丝数...")
    followers_map = {}
    for i, (uid, token) in enumerate(unique_users.items(), 1):
        followers = client.get_user_followers(uid, token)
        followers_map[uid] = followers

        if followers > 0:
            print(f"[{i}/{len(unique_users)}] {uid}: {followers} 粉丝")

    # 筛选低粉爆文
    print(f"\n[INFO] 筛选低粉爆文...")
    viral_notes = []
    for note in all_candidates:
        followers = followers_map.get(note["user_id"], 999999)
        if followers < 20000 and note["likes"] >= 1000:
            note["followers"] = followers
            viral_notes.append(note)

    print(f"[INFO] 符合条件: {len(viral_notes)} 条低粉爆文")

    if len(viral_notes) > 0:
        print("\n" + "=" * 60)
        print("✅ 执行完成")
        print("=" * 60)
        print(f"\n📊 结果:")
        print(f"  • 符合条件的低粉爆文: {len(viral_notes)} 条")
        print(f"\n🔥 TOP 3 预览:")
        for i, note in enumerate(viral_notes[:3], 1):
            print(f"  {i}. {note['title'][:40]}... | {note['likes']}赞 | {note['followers']}粉")
    else:
        print("[WARN] 未找到符合条件的低粉爆文")

if __name__ == "__main__":
    main()

